steps.command:
cat > /tmp/diag.exp <<'EXP'
set timeout 30
log_user 1
spawn nc -U /tmp/alpine.serial
expect {
  "login:" { send "root\r"; exp_continue }
  "Password:" { send "\r"; exp_continue }
  "localhost:~#" { }
  timeout { puts "TIMEOUT_LOGIN"; exit 1 }
}
send "export PS1='P> '\r"
expect "P> "
send "id; uname -a; ip -o addr; ls /media/cdrom; cat /etc/apk/repositories; ls /etc/ssh 2>/dev/null; echo DIAGDONE\r"
expect "DIAGDONE"
expect "P> "
send "\x01" 
send "\x04"
expect eof
EXP
expect -f /tmp/diag.exp 2>&1 | tail -c 5000

cat > /tmp/diag.exp <<'EXP'
set timeout 30
log_user 1
spawn nc -U /tmp/alpine.serial
after 500
send "\r"
expect {
  "login:" { send "root\r"; exp_continue }
  "Password:" { send "\r"; exp_continue }
  "localhost:~#" { }
  "# " { }
  timeout { puts "TIMEOUT_LOGIN"; exit 1 }
}
send "export PS1='P> '\r"
expect "P> "
send "id; uname -a; ip -o addr; ls /media/cdrom; cat /etc/apk/repositories; ls /etc/ssh 2>/dev/null; echo DIAGDONE\r"
expect "DIAGDONE"
expect "P> "
send "\x04"
expect eof
EXP
expect -f /tmp/diag.exp 2>&1 | tail -c 6000

cat > /tmp/run.exp <<'EXP'
set timeout 90
log_user 1
set cmd [lindex $argv 0]
spawn nc -U /tmp/alpine.serial
after 300
send "\r"
expect {
  "login:" { send "root\r"; exp_continue }
  "Password:" { send "\r"; exp_continue }
  "P> " { }
  "# " { send "export PS1='P> '\r"; exp_continue }
  timeout { puts "TIMEOUT_LOGIN"; exit 1 }
}
send "$cmd\r"
expect "ENDMARKER"
expect "P> "
send "\x04"
expect eof
EXP
expect -f /tmp/run.exp 'ip link; echo ---; ifconfig -a; echo ---; ls /sys/class/net; echo ---; lsmod | head -40; echo ---; dmesg | grep -i -E "virtio|eth|network|e1000" | tail -30; echo ENDMARKER' 2>&1 | tail -c 8000

cat > /tmp/setup1.exp <<'EXP'
set timeout 240
log_user 1
spawn nc -U /tmp/alpine.serial
after 300
send "\r"
expect {
  "login:" { send "root\r"; exp_continue }
  "Password:" { send "\r"; exp_continue }
  "P> " { }
  "# " { send "export PS1='P> '\r"; exp_continue }
  timeout { puts "TIMEOUT_LOGIN"; exit 1 }
}
send "ip link set eth0 up; udhcpc -i eth0 -q -n -t 5 -T 3; ip -o addr show eth0; echo /media/cdrom/apks > /etc/apk/repositories; apk update; apk add openssh; echo ---TOOLS---; which sshd chpasswd passwd ssh-keygen; echo ENDMARKER\r"
expect {
  "ENDMARKER" { }
  timeout { puts "TIMEOUT_CMD"; exit 2 }
}
expect "P> "
send "\x04"
expect eof
EXP
expect -f /tmp/setup1.exp 2>&1 | tail -c 8000

cat > /tmp/setup2.exp <<'EXP'
set timeout 120
log_user 1
spawn nc -U /tmp/alpine.serial
after 300
send "\r"
expect {
  "login:" { send "root\r"; exp_continue }
  "Password:" { send "\r"; exp_continue }
  "P> " { }
  "# " { send "export PS1='P> '\r"; exp_continue }
  timeout { puts "TIMEOUT_LOGIN"; exit 1 }
}
send "ssh-keygen -A; echo 'root:password123' | chpasswd; sed -i 's/^#*PermitRootLogin.*/PermitRootLogin yes/' /etc/ssh/sshd_config; sed -i 's/^#*PasswordAuthentication.*/PasswordAuthentication yes/' /etc/ssh/sshd_config; grep -nE '^(PermitRootLogin|PasswordAuthentication)' /etc/ssh/sshd_config; rc-service sshd start; sleep 2; netstat -ltnp | grep :22; echo ENDMARKER\r"
expect {
  "ENDMARKER" { }
  timeout { puts "TIMEOUT_CMD"; exit 2 }
}
expect "P> "
send "\x04"
expect eof
EXP
expect -f /tmp/setup2.exp 2>&1 | tail -c 6000

nc -zv -w 3 localhost 2222 2>&1; cat > /tmp/sshtest.exp <<'EXP'
set timeout 30
log_user 1
spawn ssh -p 2222 -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o PreferredAuthentications=password -o PubkeyAuthentication=no root@localhost
expect {
  "password:" { send "password123\r"; exp_continue }
  "Permission denied" { puts "AUTH_FAIL"; exit 1 }
  "# " { }
  timeout { puts "SSH_TIMEOUT"; exit 2 }
}
send "id; hostname; echo SSH_OK\r"
expect "SSH_OK"
send "exit\r"
expect eof
EXP
expect -f /tmp/sshtest.exp 2>&1 | tail -c 4000
